contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Deposit an amount into c, then call withdrawAll and check observable effects.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record balances before any interaction
        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        // perform deposit (state-changing) as a top-level call
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // attempt first withdrawAll and record if it reverted
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // record balances after first withdraw attempt
        uint cBalanceAfterFirst = address(c).balance;
        uint selfBalanceAfterFirst = address(this).balance;

        // attempt second withdrawAll and record if it reverted
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // record balances after second withdraw attempt
        uint cBalanceAfterSecond = address(c).balance;
        uint selfBalanceAfterSecond = address(this).balance;

        // General rule:
        // Either the first withdrawAll reverted, or (if it didn't) then:
        //  - c's balance did not increase overall (it can only decrease or stay same): cBalanceAfterSecond <= cBalanceBefore + amount
        //  - the second withdrawAll did not further increase this contract's balance (no double payout): selfBalanceAfterSecond <= selfBalanceAfterFirst
        assert(
            firstReverted || (
                cBalanceAfterSecond <= cBalanceBefore + amount
                && selfBalanceAfterSecond <= selfBalanceAfterFirst
            )
        );
    }

    receive() external payable {}
}

